import * as React from "react";
import { useState, useEffect } from "react";
import type { IRecrutimentAppProps } from "../../IRecrutimentAppProps";
import { DynamicSidebar } from "../Sidebar";
import { mockMenuData } from "../../../models/menu";

interface ICurrentUser {
  Id: number;
  Title: string;
  Email: string;
  LoginName: string;
}

type IRecruitment ={
  props: IRecrutimentAppProps
}

const RecrutimentApp: React.FC<IRecruitment> = (props) => {

  const [user, setUser] = useState<ICurrentUser | undefined>(undefined);
  const [activePath, setActivePath]     = useState("/RecurimentProcess");
   const [activeChildId, setActiveChildId] = useState<number | null>(30);

  useEffect(() => {
  }, []);

  return (
    <div>
       <DynamicSidebar
       menuData={mockMenuData}
       activePath={activePath}
       activeChildId={activeChildId}
       onMenuClick={(path, item) => {
         setActivePath(path);
         setActiveChildId(null);
       }}
       onChildClick={(path, child) => {
         setActivePath(path);
         setActiveChildId(child.Id);
       }}
     />
    </div>
  );
};

export default RecrutimentApp;